export async function runConcurrencySuite(): Promise<ScenarioResult[]> {
  const aggregate = [
    {
      name: "Scenario A: distinct keys, one vehicle",
      requests: 5,
      iterations: 50,
      successCount: 0,
      conflictCount: 0,
      captureCount: 0,
      replayVerified: true,
    },
    {
