          checkoutResponse = response(
            409,
            "VEHICLE_UNAVAILABLE",
            "Another checkout currently owns this vehicle.",
          );
        } else {
          reservationCreated = await deps.reservations.reserveIfAvailable(
            request.vehicle_id,
            request.booking_id,
          );

