    | "VEHICLE_UNAVAILABLE"
    | "IDEMPOTENCY_KEY_REUSED"
    | "MISSING_IDEMPOTENCY_KEY"
    | "INVALID_REQUEST"
    | "CHECKOUT_FAILED";
  message: string;
}

