export interface CheckoutResponse {
  status: CheckoutStatus;
  body: CheckoutResponseBody;
}

export type IdempotencyClaim =
  | { kind: "claimed" }
  | { kind: "in_progress" }
  | { kind: "replay"; response: CheckoutResponse }
  | { kind: "payload_mismatch" };

