  /** Atomically claims a new key or reports its existing state. */
  claim(key: string, payloadFingerprint: string): Promise<IdempotencyClaim>;
  complete(
    key: string,
    payloadFingerprint: string,
    response: CheckoutResponse,
  ): Promise<void>;
}

